    UPDATE `dbxdb`.`featureaction` SET `approveFeatureAction` = 'INTERNATIONAL_ACCOUNT_FUND_TRANSFER_RECEPIENT_APPROVE' WHERE `id` = 'INTERNATIONAL_ACCOUNT_FUND_TRANSFER_CREATE_RECEPIENT';
