    UPDATE `dbxdb`.`featureaction` SET `approveFeatureAction` = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_RECEPIENT_APPROVE' WHERE `id` = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_CREATE_RECEPIENT';
    UPDATE `dbxdb`.`featureaction` SET `approveFeatureAction` = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_RECEPIENT_APPROVE' WHERE `id` = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_DELETE_RECEPIENT';
