    UPDATE `dbxdb`.`featureaction` SET `approveFeatureAction` = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_RECEPIENT_APPROVE' WHERE `id` = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_EDIT_RECEPIENT_LINKAGE';
    UPDATE `dbxdb`.`featureaction` SET `approveFeatureAction` = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_RECEPIENT_APPROVE' WHERE `id` = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_EDIT_RECEPIENT_OPTIONAL';

    UPDATE `dbxdb`.`featureaction` SET `approveFeatureAction` = 'INTRA_BANK_FUND_TRANSFER_RECEPIENT_APPROVE' WHERE `id` = 'INTRA_BANK_FUND_TRANSFER_CREATE_RECEPIENT';
    UPDATE `dbxdb`.`featureaction` SET `approveFeatureAction` = 'INTRA_BANK_FUND_TRANSFER_RECEPIENT_APPROVE' WHERE `id` = 'INTRA_BANK_FUND_TRANSFER_DELETE_RECEPIENT';
